using System;
using System.IO;
using System.Linq;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

namespace PortaCapena.OdooJsonRpcClient.Example.Infrastructure
{
    /// <summary>
    /// Compiles C# code generated by <see cref="Converters.OdooModelMapper.GetDotNetModel"/> to check that it is valid and usable.
    /// </summary>
    public static class GeneratedModelCompiler
    {
        /// <summary>
        /// Compiles the model code with the usings a user pastes it with.
        /// </summary>
        /// <returns>Compilation errors; empty when the code compiles.</returns>
        public static string[] Compile(string modelCode)
        {
            return CreateCompilation(modelCode).GetDiagnostics()
                .Where(x => x.Severity == DiagnosticSeverity.Error)
                .Select(x => x.ToString())
                .ToArray();
        }

        /// <summary>
        /// Compiles the model code and returns the generated model type, e.g. <c>AccountMoveOdooModel</c> for <c>account.move</c>.
        /// </summary>
        public static Type CompileModelType(string tableName, string modelCode)
        {
            using (var stream = new MemoryStream())
            {
                var emit = CreateCompilation(modelCode).Emit(stream);
                if (!emit.Success)
                    throw new InvalidOperationException(string.Join(Environment.NewLine, emit.Diagnostics.Where(x => x.Severity == DiagnosticSeverity.Error)));

                var assembly = System.Reflection.Assembly.Load(stream.ToArray());
                return assembly.GetType("GeneratedModels." + Converters.OdooModelMapper.ConvertOdooNameToDotNet(tableName) + "OdooModel", throwOnError: true);
            }
        }

        /// <summary>
        /// Compilation of the model code with usings and references of the library, Newtonsoft.Json and the runtime.
        /// </summary>
        public static CSharpCompilation CreateCompilation(string modelCode)
        {
            var code = string.Join(Environment.NewLine,
                "using System;",
                "using System.Runtime.Serialization;",
                "using Newtonsoft.Json;",
                "using Newtonsoft.Json.Converters;",
                "using PortaCapena.OdooJsonRpcClient.Attributes;",
                "using PortaCapena.OdooJsonRpcClient.Converters;",
                "using PortaCapena.OdooJsonRpcClient.Models;",
                "namespace GeneratedModels {",
                modelCode,
                "}");

            var references = ((string)AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES")).Split(Path.PathSeparator)
                .Concat(new[] { typeof(OdooClient).Assembly.Location, typeof(Newtonsoft.Json.JsonPropertyAttribute).Assembly.Location })
                .Distinct()
                .Select(path => MetadataReference.CreateFromFile(path));

            return CSharpCompilation.Create(
                "GeneratedModels" + Guid.NewGuid().ToString("N"),
                new[] { CSharpSyntaxTree.ParseText(code) },
                references,
                new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        }
    }
}
